/**
 * frontend/src/api_service.js - CORRIGÉ POUR IMAGES
 * À REMPLACER
 * ✅ enrollFromImage accepte base64 ou data:image
 */

import axios from "axios";

// ✅ URL de base - SANS /api/
const API_BASE_URL = "http://localhost:8000";

const api = axios.create({
  baseURL: API_BASE_URL,
  timeout: 15000,
  headers: {
    "Content-Type": "application/json"
  }
});

/**
 * ============ REQUEST INTERCEPTOR ============
 */
api.interceptors.request.use(
  (config) => {
    const token = localStorage.getItem('access_token');
    if (token) {
      config.headers.Authorization = `Bearer ${token}`;
    }
    console.log(`📤 [${config.method.toUpperCase()}] ${config.url}`);
    return config;
  },
  (error) => {
    console.error('❌ Request Error:', error.message);
    return Promise.reject(error);
  }
);

/**
 * ============ RESPONSE INTERCEPTOR ============
 */
api.interceptors.response.use(
  (response) => {
    console.log(`✅ [${response.status}] ${response.config.url}`);
    return response;
  },
  (error) => {
    const status = error.response?.status;
    const url = error.config?.url;
    const data = error.response?.data;

    console.error('❌ API Error:', {
      status,
      url,
      data,
      message: error.message
    });

    if (status === 401) {
      localStorage.removeItem('access_token');
      localStorage.removeItem('refresh_token');
      localStorage.removeItem('user');
      window.location.href = '/';
    }

    return Promise.reject(error);
  }
);

/**
 * ============ STUDENTS API ============
 */
export const studentsAPI = {
  getAll: () => {
    console.log('🎓 Fetching all students...');
    return api.get("/students/");
  },

  getOne: (studentId) => {
    console.log(`🎓 Fetching student ${studentId}...`);
    return api.get(`/students/${studentId}/`);
  },

  create: (data) => {
    console.log('🎓 Creating new student...', data);
    return api.post("/students/", data);
  },

  /**
   * ✅ Enroll student from base64 image (DATA URL or raw base64)
   * @param {string} name - Student name
   * @param {string} email - Student email
   * @param {string} imageBase64 - Image as data:image/jpeg;base64,... or raw base64
   */
  enrollFromImage: (name, email, imageBase64) => {
    console.log('📸 Enrolling student from image...', { name, email });
    console.log('📸 Image size:', imageBase64.length, 'bytes');

    // ✅ Vérifier si c'est un data URL ou raw base64
    let base64Data = imageBase64;

    if (imageBase64.startsWith('data:')) {
      // ✅ Data URL: data:image/jpeg;base64,ABC123...
      // Extraire juste la partie base64
      base64Data = imageBase64.split(',')[1];
      console.log('✅ Extracted base64 from data URL');
    }

    return api.post("/students/enroll_from_image/", {
      name,
      email,
      image_base64: base64Data  // ✅ Envoyer base64 au lieu de image_path!
    });
  },

  search: (query) => {
    console.log(`🔍 Searching students: "${query}"`);
    return api.post("/students/search/", { query });
  },

  getStats: () => {
    console.log('📊 Fetching student stats...');
    return api.get("/students/stats/");
  },

  update: (studentId, data) => {
    console.log(`🎓 Updating student ${studentId}...`);
    return api.put(`/students/${studentId}/`, data);
  },

  delete: (studentId) => {
    console.log(`🎓 Deleting student ${studentId}...`);
    return api.delete(`/students/${studentId}/`);
  }
};

/**
 * ============ ATTENDANCE API ============
 */
export const attendanceAPI = {
  getTodayLog: () => {
    console.log('📋 Fetching today\'s attendance log...');
    return api.get("/attendance/");
  },

  /**
   * ✅ Recognize face from base64 embedding
   * @param {string} embeddingBase64 - 512-dim embedding as base64
   */
  recognize: (embeddingBase64) => {
    console.log('👤 Recognizing face...');
    console.log('👤 Embedding size:', embeddingBase64.length, 'bytes');

    return api.post("/attendance/recognize/", {
      embedding: embeddingBase64
    });
  },

  getStats: () => {
    console.log('📊 Fetching attendance stats...');
    return api.get("/attendance/stats/");
  },

  getStatus: () => {
    console.log('✅ Fetching attendance status...');
    return api.get("/attendance/status/");
  },

  getHistory: (studentId, days = 30) => {
    console.log(`📅 Fetching history for student ${studentId} (${days} days)...`);
    return api.get("/attendance/student_history/", {
      params: { 
        student_id: studentId, 
        days 
      }
    });
  },

  getOne: (attendanceId) => {
    console.log(`📋 Fetching attendance record ${attendanceId}...`);
    return api.get(`/attendance/${attendanceId}/`);
  }
};

/**
 * ============ UTILITY FUNCTIONS ============
 */

export const setAuthToken = (token) => {
  if (token) {
    api.defaults.headers.common['Authorization'] = `Bearer ${token}`;
  }
};

export const getAuthToken = () => {
  return localStorage.getItem('access_token');
};

export const clearAuthToken = () => {
  delete api.defaults.headers.common['Authorization'];
  localStorage.removeItem('access_token');
  localStorage.removeItem('refresh_token');
};

export default api;
